def bitwise_or_of_subsequence_sums(nums):
    bit_counts=[0]*64
    for value in nums:
        for bit in range(63):bit_counts[bit]+=value>>bit&1
    answer=0
    for bit in range(63):
        if bit_counts[bit]:answer|=1<<bit
        bit_counts[bit+1]+=bit_counts[bit]//2
    return answer

